pragma solidity ^0.8.20;

contract OwnerExample {

    address public owner;

    constructor() {
        owner = msg.sender; // deployer = owner
    }

    modifier onlyOwner() {
        require(msg.sender == owner, 'Not Owner');
        _;
    }

    // anyone can call this
    function getOwner()
        public view returns(address)
    {
        return owner;
    }

