// revert() with multiple conditions
function complexCheck(
    uint amount
) public view {
    if (msg.sender != owner) {
        revert('Not Owner');
    }
    if (amount == 0) {
        revert('Zero amount');
    }
    if (amount > 1000) {
        revert('Amount too high');
    }
}

