pragma solidity ^0.8.20;

contract ErrorExample {

    address public owner;

    constructor() { owner = msg.sender; }

    // require: checks user-provided input
    function testRequire(uint amount)
        public pure
    {
        require(amount > 0, 'Amount must be > 0');
        // continues only if amount > 0
    }

    // revert: checks condition with if-else logic
    function testRevert() public view {
        if (msg.sender != owner) {
            revert('Not Owner — use revert style');
        }
        // continues only if caller is owner
    }

    // assert: verifies internal code invariant
    function testAssert() public pure {
        uint a = 5;
        uint b = 3;
        uint result = a + b;
        // This MUST be 8 — if not, our code has a bug
        assert(result == 8);
    }

}

// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

contract ProfessionalBank {

    address public owner;
    mapping(address => uint) public balances;
    bool public paused;

    constructor() { owner = msg.sender; }

    // single modifier — reused on all admin functions
    modifier onlyOwner() {
        require(msg.sender == owner, 'Not Owner');
        _;
    }

    modifier notPaused() {
        require(!paused, 'Contract is paused');
        _;
    }

    // anyone can deposit — but only when not paused
    function deposit() public payable notPaused {
        require(msg.value > 0, 'Send some ETH');
        balances[msg.sender] += msg.value;
    }

    // owner only: pause the contract
    function pause() public onlyOwner {
        paused = true;
    }

    // owner only: unpause
    function unpause() public onlyOwner {
        paused = false;
    }

    // owner only: check total ETH held
    function getVaultBalance()
        public view onlyOwner
        returns(uint)
    {
        return address(this).balance;
    }

}
